import logo from "./logo.svg";
import "./App.css";
import { useApp } from "./context/AppContext";

async function audioDeviceClicked(e) {}

function App() {
  const { devices, currentDevice, setCurrentDevice, loading, error } = useApp();

  if (loading) return <p> Loading Devices... </p>;
  if (error) return <p>error</p>;

  console.log(devices);
  console.log("Is array:", Array.isArray(devices));
  console.log(currentDevice);

  return (
    <div className="App">
      <header className="App-header">
        <h1>Audio Switcher</h1>
        <ul className="audio-selector">
          {devices.map((i) => (
            <li
              key={i.InstanceID}
              className={
                currentDevice.InstanceId === i.InstanceId
                  ? "selected-device"
                  : ""
              }
              onClick={() => audioDeviceClicked(i)}
            >
              {i.FriendlyName}
            </li>
          ))}
        </ul>
      </header>
    </div>
  );
}

export default App;
